            int n0 = tileCol * BN + wn * 32 + 0 + 2 * t, n1 = n0 + 1;
            float bias0 = 0f, bias1 = 0f;
            if (hasBias != 0) { if (n0 < N) bias0 = PrecisionConvert.ConvertToSingle(bias[n0]); if (n1 < N) bias1 = PrecisionConvert.ConvertToSingle(bias[n1]); }
            if (m0 < M)
