            {
                if (n0 < N) { float v = Activate(c332.Value + bias0, act); if (hasRes != 0) v += res[(long)m1 * N + n0]; C[(long)m1 * N + n0] = v; }
                if (n1 < N) { float v = Activate(c333.Value + bias1, act); if (hasRes != 0) v += res[(long)m1 * N + n1]; C[(long)m1 * N + n1] = v; }
